def rule(event):
    if event.get('eventName') not in ['PutBucketAcl', 'PutBucketPolicy']:
        return False
    request_params = event.get('requestParameters', {})
    acl = str(request_params).lower()
    return 'allusers' in acl or 'authenticatedusers' in acl

def title(event):
